|      صفحهٔ خطا. کارنامهٔ خالی سندِ خالی است، نه شکست.
|   ۲. سند چاپی است: بدون منو و سایهٔ پنل، تاریخ شمسی، ارقام فارسی، امضا.
|   ۳. مجوز در لایه route اعمال می‌شود؛ امور مالی و پذیرش نمره نمی‌بینند.
|
| ساعت حضور از جلساتِ واقعاً حاضر در می‌آید، نه از جلساتِ برنامه‌ریزی‌شده:
| غیبت نباید به عنوان ساعت روی کارنامه ثبت شود.
*/

class TranscriptTest extends TestCase
{
    use RefreshDatabase;

    private function actingAsRole(Role $role): User
    {
        $user = User::factory()->role($role)->create();

        $this->actingAs($user);

        return $user;
    }

    private function student(): Student
    {
        return Student::factory()->create();
    }

    /** دانش‌آموز با ثبت‌نام قطعی در یک دوره. */
    private function enrolled(Student $student, ?Course $course = null): Course
    {
        $course ??= Course::factory()->create();

        CourseEnrollment::enroll($student, $course)->confirm();

        return $course;
    }

    // ── دانش‌آموز بدون نمره ─────────────────────────────────

    public function test_a_student_without_grades_still_gets_a_transcript(): void
    {
        // الزام issue: سند باید تولید شود و خطا ندهد، حتی وقتی نمره‌ای نیست
        $this->actingAsRole(Role::Admin);
        $student = $this->student();
        $this->enrolled($student);

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('کارنامهٔ رسمی')
            ->assertSee('فاقد سابقه');
    }

    public function test_a_student_with_no_enrollment_also_gets_a_document(): void
    {
        // بدون ثبت‌نام هم سند صادر می‌شود؛ خالی بودنِ پرونده دلیلِ خطای ۵۰۰ نیست
        $this->actingAsRole(Role::Admin);

        $this->get(route('students.transcript', $this->student()))
            ->assertOk()
            ->assertSee('فاقد سابقه');
    }

    public function test_the_empty_transcript_does_not_invent_a_zero_average(): void
    {
        // صفرِ ساختگی یعنی «میانگین صفر» روی سند رسمی — یعنی اتهام
        $this->actingAsRole(Role::Admin);
        $student = $this->student();
        $this->enrolled($student);

        $response = $this->get(route('students.transcript', $student))->assertOk();

        $response->assertSee('میانگین کل');
        $response->assertDontSee('میانگین کل:</th>' . "\n" . '0');
        $response->assertSee(to_persian_digits('—'));
    }

    // ── ریزنمرات و جمع‌بندی ─────────────────────────────────

    public function test_the_transcript_lists_the_breakdown_and_the_final_score(): void
    {
        $this->actingAsRole(Role::Admin);
        $student = $this->student();
        $course = $this->enrolled($student);

        Grade::record($student, $course, GradeType::Homework, 'تکلیف اول', 18);
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 16);

        $response = $this->get(route('students.transcript', $student))->assertOk();

        $response
            ->assertSee('تکلیف اول')
            ->assertSee('پایان‌ترم')
            ->assertSee(to_persian_digits('18.00/20.00'))
            ->assertDontSee('فاقد سابقه');

        // میانگین وزنی: تکلیف ۹۰٪ با وزن ۳ و پایان‌ترم ۸۰٪ با وزن ۵ → ۱۶٫۷۵
        $response->assertSee(to_persian_digits('16.75'));
    }

    public function test_the_pass_status_is_printed_per_course(): void
    {
        $this->actingAsRole(Role::Admin);
        $student = $this->student();

        $passed = $this->enrolled($student);
        Grade::record($student, $passed, GradeType::Final, 'پایان‌ترم', 19);

        $failed = $this->enrolled($student);
        Grade::record($student, $failed, GradeType::Final, 'پایان‌ترم', 4);

        $response = $this->get(route('students.transcript', $student))->assertOk();

        $response->assertSee('قبول')->assertSee('مردود');
    }

    public function test_the_transcript_carries_the_academy_header_and_the_signatures(): void
    {
