    // ── چاپ ────────────────────────────────────────────────

    public function test_the_transcript_is_print_ready_without_the_panel_chrome(): void
    {
        // پنل منو و سایه دارد و روی کاغذ می‌افتد؛ سند رسمی باید تمیز باشد
        $this->actingAsRole(Role::Admin);
        $student = $this->student();
